#include <iostream>
#include <string>
#include <vector>
#include <sstream>

int main() {
    std::string len, st;
    std::getline(std::cin, len);
    std::getline(std::cin, st);

    int cnt = 0;
    int maxl = 0;
    size_t i = 0;
    size_t j = 0;

    while (i < st.find(')')) {
        size_t start_idx = st.find('(', i);
        if (start_idx == std::string::npos || start_idx >= st.size()) break;
        size_t end_idx = st.find(')', start_idx);
        if (end_idx == std::string::npos) break;

        std::string s = st.substr(j, start_idx - j);
        std::istringstream ss(s);
        std::string token;
        while (std::getline(ss, token, '_')) {
            if (token.length() > maxl)
                maxl = token.length();
        }

        std::string inside = st.substr(start_idx + 1, end_idx - start_idx - 1);
        std::istringstream inside_stream(inside);
        while (inside_stream >> token) {
            if (!token.empty())
                cnt++;
        }

        j = end_idx + 1;
        i = end_idx;
    }

    // Process the remaining part after the last ')'
    std::string s = st.substr(j);
    std::istringstream ss(s);
    std::string token;
    while (std::getline(ss, token, '_')) {
        if (token.length() > maxl)
            maxl = token.length();
    }

    std::cout << maxl << " " << cnt << std::endl;

    return 0;
}
